INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5628, 9323, 'tt0104541', NULL, 'The Jacksons: An American Dream', 'The Jacksons: An American Dream', 'tv', 1992, 'https://image.tmdb.org/t/p/w500/4fHM1tTWf0n8mzxh4d1G2er7yPx.jpg', 'https://image.tmdb.org/t/p/original/nBJB5xBazUbhYTQff0MlEGJf2Bq.jpg', 'The Jacksons are your average working-class family in Gary, Indiana; but when their father Joseph discovers the kids have an extraordinary musical talent, they form a band. Winning talent show after talent show, they soon hit it big when Motown comes calling. From there, they become the now famous Jackson 5. But along the way, their success brings trouble and turmoil.', NULL, NULL, 6.9599, 6.816, 0, 1.02, '2026-07-30 18:28:39', '2026-07-30 18:28:39');
