INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5630, 291272, 'tt3520418', NULL, 'We Are Still Here', 'We Are Still Here', 'movie', 2015, 'https://image.tmdb.org/t/p/w500/f8Btwn93gNycI1tFo29Gy1zB5kv.jpg', 'https://image.tmdb.org/t/p/original/bUV1ObIIeCzIUKE4iucetXvFIh7.jpg', 'After the death of their college age son, Anne and Paul Sacchetti relocate to the snowswept New England hamlet of Aylesbury, a sleepy village where all is most certainly not as it seems. When strange sounds and eerie feelings convince Anne that her son''s spirit is still with them, they invite an eccentric, New Age couple to help them get to the bottom of the mystery.', NULL, NULL, 1.5914, 5.614, 0, 9.95999999999999907e+00, '2026-07-30 18:28:39', '2026-07-30 18:28:39');
