INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5645, 11929, 'tt0109642', NULL, 'Dolores Claiborne', 'Dolores Claiborne', 'movie', 1995, 'https://image.tmdb.org/t/p/w500/yqY5h9kI456xXRWv6u9t0Axn9CS.jpg', 'https://image.tmdb.org/t/p/original/9vJ57nbL4hWJrmsyjKTxiGXqrBU.jpg', 'Dolores Claiborne was accused of killing her abusive husband twenty years ago, but the court''s findings were inconclusive and she was allowed to walk free. Now she has been accused of killing her employer, Vera Donovan, and this time there is a witness who can place her at the scene of the crime. Things look bad for Dolores when her daughter Selena, a successful Manhattan magazine writer, returns to cover the story.', NULL, NULL, 3.8001, 7.3, 0, 1.02, '2026-07-30 18:28:39', '2026-07-30 18:28:39');
