INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5660, 9894, 'tt0115798', NULL, 'The Cable Guy', 'The Cable Guy', 'movie', 1996, 'https://image.tmdb.org/t/p/w500/YJt9l3RdrRohI95btQKPXwpdii.jpg', 'https://image.tmdb.org/t/p/original/nj0rIFyjZ0GUOQYnGM8YyGR3CmS.jpg', 'When recently single Steven moves into his new apartment, cable guy Chip comes to hook him up—and doesn''t let go. Initially, Chip is just overzealous in his desire to be Steven''s pal, but when Steven tries to end the ''friendship'', Chip shows his dark side. He begins stalking Steven, who''s left to fend for himself because no one else can believe Chip''s capable of such behaviour.', NULL, NULL, 4.6522, 5.999, 0, 1.04, '2026-07-30 18:28:39', '2026-07-30 18:28:39');
