INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5667, 22894, 'tt1038686', NULL, 'Legion', 'Legion', 'movie', 2010, 'https://image.tmdb.org/t/p/w500/ykocDqwg5PRUopnBVb1x1DWnEJF.jpg', 'https://image.tmdb.org/t/p/original/7HzdWt7Rz3VeoHk5QEBEZaa0m1S.jpg', 'When God loses faith in humankind, he sends his legion of angels to bring on the Apocalypse. Humanity''s only hope for survival lies in a group of strangers trapped in an out-of-the-way, desert diner with the Archangel Michael.', NULL, NULL, 5.8916, 5.911, 0, 1.19, '2026-07-30 18:28:39', '2026-07-30 18:28:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5668, 898, 'tt0055798', NULL, 'Birdman of Alcatraz', 'Birdman of Alcatraz', 'movie', 1962, 'https://image.tmdb.org/t/p/w500/6EODLN11HTX4l2cmakAhWIoJLF.jpg', 'https://image.tmdb.org/t/p/original/1J6QXImtqIQxiOdVTonLV5IbRwA.jpg', 'After killing a prison guard, convict Robert Stroud faces life imprisonment in solitary confinement. Driven nearly mad by loneliness and despair, Stroud''s life gains new meaning when he happens upon a helpless baby sparrow in the exercise yard and nurses it back to health. Despite having only a third grade education, Stroud goes on to become a renowned ornithologist and achieves a greater sense of freedom and purpose behind bars than most people find in the outside world.', NULL, NULL, 1.9648, 7.497, 0, 1.73, '2026-07-30 18:28:39', '2026-07-30 18:28:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5669, 630, 'tt0032138', NULL, 'The Wizard of Oz', 'The Wizard of Oz', 'movie', 1939, 'https://image.tmdb.org/t/p/w500/uCC3j4pV9eOZwzDUWp2ilbcTf1f.jpg', 'https://image.tmdb.org/t/p/original/g1OvTd1eF346vmx8qsJnjaiooZ6.jpg', 'Young Dorothy finds herself in a magical world where she makes friends with a lion, a scarecrow and a tin man as they make their way along the yellow brick road to talk with the Wizard and ask for the things they miss most in their lives. The Wicked Witch of the West is the only thing that could stop them.', NULL, NULL, 15.5336, 7.583, 0, 3.06333333333333346e+00, '2026-07-30 18:28:39', '2026-07-30 18:28:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5670, 19379, 'tt0082199', NULL, 'Condorman', 'Condorman', 'movie', 1981, 'https://image.tmdb.org/t/p/w500/wRe9kAvjN5IGAjPd0oCKhjyQDt0.jpg', 'https://image.tmdb.org/t/p/original/kJn4aK6QMn890jnXEeEDLm9zDyK.jpg', 'Comic artist and writer Woody performs a simple courier operation for his friend Harry who works for the CIA. But when he successfully fends off hostile agents, he earns the respect of the beautiful Natalia, who requests his assistance for her defection. Woody uses this request as leverage to use the CIA''s resources to bring his comic book creation, Condorman, to life to battle the evil Krokov.', NULL, NULL, 1.3808, 5.5, 0, 1.08, '2026-07-30 18:28:39', '2026-07-30 18:28:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5671, 943134, 'tt16606592', NULL, 'The Animal Kingdom', 'Le Règne animal', 'movie', 2023, 'https://image.tmdb.org/t/p/w500/39AiQnXlXOjoqBSkiUpTG80rXLw.jpg', 'https://image.tmdb.org/t/p/original/H41DJiw7Q8xn6bWC75eyaavp9L.jpg', 'In a world hit by a wave of mutations transforming humans into animals, François does everything he can to save his wife. As some of the creatures disappear into a nearby forest, he and their son Émile embark on a quest that will change their lives forever.', NULL, NULL, 3.0473, 6.945, 0, 2.045, '2026-07-30 18:28:39', '2026-07-30 18:28:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5672, 1022690, 'tt1660648', NULL, 'Ricky Stanicky', 'Ricky Stanicky', 'movie', 2024, 'https://image.tmdb.org/t/p/w500/oJQdLfrpl4CQsHAKIxd3DJqYTVq.jpg', 'https://image.tmdb.org/t/p/original/wfdHCilp8cNPK7tK4jLgdUT7703.jpg', 'When three childhood best friends pull a prank gone wrong, they invent the imaginary Ricky Stanicky to get them out of trouble. Twenty years later, the trio still uses the nonexistent Ricky as a handy alibi for their immature behavior. But when their spouses and partners get suspicious and demand to finally meet the fabled Mr. Stanicky, the guilty trio decide to hire a washed-up actor and raunchy celebrity impersonator to bring him to life.', NULL, NULL, 5.123, 6.537, 0, 1.07, '2026-07-30 18:28:39', '2026-07-30 18:28:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5673, 28638, 'tt0142181', NULL, 'The Bird People in China', '中国の鳥人', 'movie', 1998, 'https://image.tmdb.org/t/p/w500/civu1OxSYyxywfEOeMyCZoAOt7H.jpg', 'https://image.tmdb.org/t/p/original/scfBpNaw7LZIV6NtDlC01HCjEpT.jpg', 'Wada, a salary man, is enlisted to venture off to China to investigate a potential Jade mine. After his arrival, Wada encounters a violent, yet sentimental, yakuza, who takes the liberty of joining his adventure through China. Led on their long and disastrous journey to the mine by Shen, the three men come across something even more magical and enticing.', NULL, NULL, 1.0539, 7.18, 0, 1.04, '2026-07-30 18:28:39', '2026-07-30 18:28:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5674, 102651, 'tt1587310', NULL, 'Maleficent', 'Maleficent', 'movie', 2014, 'https://image.tmdb.org/t/p/w500/ik8PugpL41s137RAWEGTAWu0dPo.jpg', 'https://image.tmdb.org/t/p/original/bNiiUCQUD7ij5Ybh2GoWSZwqAb1.jpg', 'A beautiful, pure-hearted young woman, Maleficent has an idyllic life growing up in a peaceable forest kingdom, until one day when an invading army threatens the harmony of the land. She rises to be the land''s fiercest protector, but she ultimately suffers a ruthless betrayal – an act that begins to turn her heart into stone. Bent on revenge, Maleficent faces an epic battle with the invading King''s successor and, as a result, places a curse upon his newborn infant Aurora. As the child grows, Maleficent realizes that Aurora holds the key to peace in the kingdom – and to Maleficent''s true happiness as well.', NULL, NULL, 12.5323, 7.088, 0, 2.215, '2026-07-30 18:28:39', '2026-07-30 18:28:39');
