INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5683, 544504, 'tt7005962', NULL, 'Moi, maman, ma mère et moi', 'Moi, maman, ma mère et moi', 'movie', 2019, 'https://image.tmdb.org/t/p/w500/frAYZwfG3lJdIR6qosjxdu9RFzL.jpg', 'https://image.tmdb.org/t/p/original/tKUAgc5GLXHWdjVKzOgqtwtgt7b.jpg', 'Benedict missed Mother''s funeral. He was stuck in the Eurostar. In the offbeat as always, and a little pitiful, he joined the family home to find his brother, his two sisters - and in a merry bazaar, many memories. There, in the remnants of his childhood, in the intimacy of his room, he sees her - She is waiting for him. And she will not let go.', NULL, NULL, 0.473, 5.1, 0, 1.01, '2026-07-30 18:28:39', '2026-07-30 18:28:39');
