INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5771, 43003, 'tt0072962', NULL, 'F for Fake', 'Vérités et Mensonges', 'movie', 1973, 'https://image.tmdb.org/t/p/w500/fVeIDxS73CrosoeVOaefQuCUGZg.jpg', 'https://image.tmdb.org/t/p/original/kwwuAQpPvewf4voKVMN98KcXEPM.jpg', 'Documents the lives of infamous fakers Elmyr de Hory and Clifford Irving. De Hory, who later committed suicide to avoid more prison time, made his name by selling forged works of art by painters like Picasso and Matisse. Irving was infamous for writing a fake autobiography of Howard Hughes. Welles moves between documentary and fiction as he examines the fundamental elements of fraud and the people who commit fraud at the expense of others.', NULL, NULL, 1.3817, 7.407, 0, 1.01, '2026-07-30 18:28:39', '2026-07-30 18:28:39');
