INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5804, 89883, 'tt1536440', NULL, 'Stuck Between Stations', 'Stuck Between Stations', 'movie', 2011, 'https://image.tmdb.org/t/p/w500/umhPhNHiEziObUjaBjicQob2r9J.jpg', 'https://image.tmdb.org/t/p/original/83KEAzR1IEauLjGYKwzG17G229N.jpg', 'A decade after they graduated from high school and went their separate ways, Casper, a soldier haunted by the horrors of war, and Rebecca, a whip-smart graduate student with a shaky future, reunite by chance and get to know each other over the course of an accidental tour of the little-known underbelly of Minneapolis. The evening''s odyssey includes a bar fight, a house party, a punk-rock circus, a spontaneous burglary, a home Casper did not know he had, and a cast of strange characters, unexpected allies and disappointing friends.', NULL, NULL, 0.8217, 6.5, 0, 1.06, '2026-07-30 18:28:39', '2026-07-30 18:28:39');
