INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5820, 26477, 'tt0092608', NULL, 'Back to the Beach', 'Back to the Beach', 'movie', 1987, 'https://image.tmdb.org/t/p/w500/geA6raOQ8rnEkX31r6a8mteJCW8.jpg', 'https://image.tmdb.org/t/p/original/kUiFHTcetvLIX9FxYjC5ppRn1lB.jpg', 'Cowabunga! The surfing ''60s ride into the new wave as Frankie and Annette star in this hip update of their old-time, good-time beach movies. With special appearances by Bob Denver, Tony Dow, Pee-Wee Herman, Jerry Mathers and other familiar faces. Frankie and Annette grow up and have kids in the midwest. They return to LA to visit their daughter who is shacked up with her boyfriend and tries to hide the fact. They begin to have marriage problems when Frankie runs into Connie, who has erected a shrine to him in her night club. Their punk son has joined up with the local surf toughs, and things all come to a head when the toughs challenge the good guys to a surfing duel', NULL, NULL, 0.9022, 5.896, 0, 1.01, '2026-07-30 18:28:39', '2026-07-30 18:28:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5821, 25010, 'tt0087265', NULL, 'The Flamingo Kid', 'The Flamingo Kid', 'movie', 1984, 'https://image.tmdb.org/t/p/w500/hNCYkAXB9WIQBABXTV6Vs9kFrLY.jpg', 'https://image.tmdb.org/t/p/original/uP380OUxtBQEizzKftV8e8abvLO.jpg', 'Brooklyn teenager Jeffrey Willis, thoroughly unhappy with his modest homestead, embraces the other-world aspects of his summer job at the posh Flamingo Club. He spurns his father in favor of the patronage of smooth-talking Phil Brody and is seduced by the ample bikini charms of club member Carla Samson. But thanks to a couple of late-summer hard lessons, the teen eventually realizes that family should always come first.', NULL, NULL, 0.9892, 5.989, 0, 1.01, '2026-07-30 18:28:39', '2026-07-30 18:28:39');
