INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5823, 9591, 'tt0117887', NULL, 'That Thing You Do!', 'That Thing You Do!', 'movie', 1996, 'https://image.tmdb.org/t/p/w500/9RmZu33qHdyZFGLfhEOmkTjdNEu.jpg', 'https://image.tmdb.org/t/p/original/vxhnRV7jGncAZmf0FFHMs6rFHWn.jpg', 'A Pennsylvania band scores a hit in 1964 and rides the star-making machinery as long as it can, with lots of help from its manager. But behind the scenes, the group’s sudden fame tests their strength, their maturity and responsibility, and their ability to resist the temptations that money and notoriety always make possible.', NULL, NULL, 4.1563, 6.883, 0, 1.01, '2026-07-30 18:28:39', '2026-07-30 18:28:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5824, 13649, 'tt0810900', NULL, 'High School Musical 2', 'High School Musical 2', 'movie', 2007, 'https://image.tmdb.org/t/p/w500/kqImEYXsDIlzPpu0KxyTXIx7smW.jpg', 'https://image.tmdb.org/t/p/original/aS7M839gMmcokvUwNM3DFqOLqzu.jpg', 'The East High Wildcats are gearing up for big fun as they land the coolest summer jobs imaginable. Troy, Gabriella, Chad, and Taylor have scored sweet gigs at the Lava Springs Country Club owned by Sharpay and Ryan''s family. Sharpay''s first rule of business: Get Troy. As Troy experiences a life of privilege he''s never known, will he give up the Wildcats and Gabriella to rise to the top?', NULL, NULL, 3.8256, 6.502, 0, 2.01, '2026-07-30 18:28:39', '2026-07-30 18:28:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5825, 23514, 'tt0376136', NULL, 'The Rum Diary', 'The Rum Diary', 'movie', 2011, 'https://image.tmdb.org/t/p/w500/uErFROiMrpk7owQWKK3bpD4hSJs.jpg', 'https://image.tmdb.org/t/p/original/jxsWn2D4pk0rgtO3hBzFq9rROZ8.jpg', 'Tired of the noise and madness of New York and the crushing conventions of late Eisenhower-era America, itinerant journalist Paul Kemp travels to the pristine island of Puerto Rico to write for a local San Juan newspaper run by the downtrodden editor Lotterman. Adopting the rum-soaked lifestyle of the late ‘50s version of Hemingway’s ''The Lost Generation'', Paul soon becomes entangled with a very attractive American woman and her fiancée, a businessman involved in shady property development deals.  It is within this world that Kemp ultimately discovers his true voice as a writer and integrity as a man.', NULL, NULL, 2.5636, 5.882, 0, 1.01, '2026-07-30 18:28:39', '2026-07-30 18:28:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5826, 26484, 'tt0056860', NULL, 'Beach Party', 'Beach Party', 'movie', 1963, 'https://image.tmdb.org/t/p/w500/3Wmf7VKBIlwUSpakKDMi9LIGnP.jpg', 'https://image.tmdb.org/t/p/original/6cry2pSWo4dpT5JKgje2HBU4vFw.jpg', 'Anthropology Professor Robert Orwell Sutwell and his secretary Marianne are studying the sex habits of teenagers. The surfing teens led by Frankie and Dee Dee don''t have much sex but they sing, battle the motorcycle rats and mice led by Eric Von Zipper and dance to Dick Dale and the Del Tones.', NULL, NULL, 0.9951, 5.976, 0, 1.01, '2026-07-30 18:28:39', '2026-07-30 18:28:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5827, 5767, 'tt0062407', NULL, 'Two for the Road', 'Two for the Road', 'movie', 1967, 'https://image.tmdb.org/t/p/w500/f9GAaL5gXzSP8LhXJcAx8Remfy3.jpg', 'https://image.tmdb.org/t/p/original/mAZqXy8Ssigm1owFtwC70nT2RcB.jpg', 'Architect Mark Wallace and his wife, Joanna, travel to France to meet with an affluent client. While there, they reflect on their first decade of marriage -- memories of when they first met, of courtship, and of road trips through the French countryside. As flirtation and playful quarreling turn to boredom with the banality of married life, the Wallaces struggle to rekindle their passion, while mutual infidelity threatens to tear them apart.', NULL, NULL, 1.6828, 7.011, 0, 1.02, '2026-07-30 18:28:39', '2026-07-30 18:28:39');
