INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5845, 65218, 'tt1648204', NULL, 'Lemonade Mouth', 'Lemonade Mouth', 'movie', 2011, 'https://image.tmdb.org/t/p/w500/5Tbbxf38c16kbfezmXkPYS2tYRN.jpg', 'https://image.tmdb.org/t/p/original/lBy0tIjlc3rAy4dih74RFDIpxoP.jpg', 'When five ragtag freshman first meet in detention, it seems they have nothing in common. But, through music, they form an unbreakable bond and discover they have the makings of the greatest high school garage band in history! In the face of incredible odds, Olivia, Stella, Wen, Mohini and Charlie find they can make a real difference when they learn to lean on each other and let go of everything holding back their dreams.', NULL, NULL, 2.3781, 7.441, 0, 1.02, '2026-07-30 18:28:39', '2026-07-30 18:28:39');
