INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5847, 269, 'tt0368530', NULL, 'One Tree Hill', 'One Tree Hill', 'tv', 2003, 'https://image.tmdb.org/t/p/w500/sOrelBaAhp7DZbPTivDwKEyPslC.jpg', 'https://image.tmdb.org/t/p/original/gJOpHgHa37qnglH3dL9g63iztky.jpg', 'In Tree Hill, North Carolina two half brothers share a last name and nothing else. Brooding, blue-collar Lucas is a talented street-side basketball player, but his skills are appreciated only by his friends at the river court. Popular, affluent Nathan basks in the hero-worship of the town, as the star of his high school team. And both boys are the son of former college ball player Dan Scott whose long ago choice to abandon Lucas and his mother Karen, will haunt him long into his life with wife Deb and their son Nathan.', NULL, NULL, 87.8668, 7.8, 0, 1.02, '2026-07-30 18:28:39', '2026-07-30 18:28:39');
