INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5928, NULL, NULL, 68447, 'Superliminal', 'Superliminal', 'game', 2019, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1uqz.jpg', NULL, 'Falling asleep at 3AM, you close your eyes to the cheesy commercial of Dr. Pierce''s dream therapy program. You wake up in an unfamiliar environment, only to realize that you''re stuck in a dream - a dream where perception is reality. Welcome to Superliminal.

Superliminal is a first-person puzzle game inspired perspective and optical illusions. Players tackle impossible puzzles by thinking outside the box and learning to expect the unexpected.

This game features a wonderfully subdued world, an intriguingly voiced narrative, and things that are really weird.', 'https://www.igdb.com/games/superliminal', '["Xbox Series X|S", "PlayStation 4", "Linux", "Android", "PC (Microsoft Windows)", "iOS", "PlayStation 5", "Mac", "Xbox One", "Nintendo Switch"]', NULL, NULL, 0, 1.02, '2026-07-30 18:28:39', '2026-07-30 18:28:39');
