INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5939, 36968, 'tt0200809', NULL, 'Life-Size', 'Life-Size', 'movie', 2000, 'https://image.tmdb.org/t/p/w500/kS91p5rwK0A0VGmBISVWK6O3So5.jpg', 'https://image.tmdb.org/t/p/original/3zjR5hQnke7o3JVEKNOK9Zip81B.jpg', 'Sad and lonely after the death of her mother, Casey would do anything to see her again. But when a series of mystic mishaps mistakenly brings her fashion doll “Eve” to life instead, it changes Casey’s world forever!', NULL, NULL, 2.5685, 6.528, 0, 1.09, '2026-07-30 18:28:39', '2026-07-30 18:28:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5940, 310, 'tt0315327', NULL, 'Bruce Almighty', 'Bruce Almighty', 'movie', 2003, 'https://image.tmdb.org/t/p/w500/wqkWrOFtYnZSvIMu8Lsmz7WIvKC.jpg', 'https://image.tmdb.org/t/p/original/cgjLr9VVQzp0mYQ6IUc3JlZ8Frp.jpg', 'Bruce Nolan toils as a "human interest" television reporter in Buffalo, NY, but despite his high ratings and the love of his beautiful girlfriend, Bruce remains unfulfilled. At the end of the worst day in his life, he angrily ridicules God — and the Almighty responds, endowing Bruce with all of His divine powers.', NULL, NULL, 11.1895, 6.729, 0, 1.09, '2026-07-30 18:28:39', '2026-07-30 18:28:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5941, 28121, 'tt0117891', NULL, 'A Thin Line Between Love and Hate', 'A Thin Line Between Love and Hate', 'movie', 1996, 'https://image.tmdb.org/t/p/w500/wo9AGi5LlFXZUj8MDPq3eKCUMpd.jpg', 'https://image.tmdb.org/t/p/original/1Y7ZE94BTwXhYDDzzS7MY8sXBr1.jpg', 'Nightclub manager Darnell Wright is a perpetual playboy who is almost as devoted to his job as he is to the pursuit of beautiful women. After he sets his sights on the ultra-classy Brandi Web, he launches an all-out assault to win her heart. Ultimately, charm, lust and passion prevail, but Darnell learns the hard way that when you play, you pay. Brandi is much harder to get rid of than she was to get--especially when she realizes that she has a rival vying for Darnell''s affection. When he finally decides to call it quits, Brandi becomes an obsessed femme fatale stalking the new love of her life.', NULL, NULL, 1.3926, 5.663, 0, 1.01, '2026-07-30 18:28:39', '2026-07-30 18:28:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5942, 243940, 'tt2918436', NULL, 'The Lazarus Effect', 'The Lazarus Effect', 'movie', 2015, 'https://image.tmdb.org/t/p/w500/4aq0TOLvITU3iWRUfxlRc83lMz1.jpg', 'https://image.tmdb.org/t/p/original/nMlsS5v0BY9W1GhRBUNrRPF90Xh.jpg', 'Medical researcher Frank, his fiancee Zoe and their team have achieved the impossible: they have found a way to revive the dead. After a successful, but unsanctioned, experiment on a lifeless animal, they are ready to make their work public. However, when their dean learns what they''ve done, he shuts them down. Zoe is killed during an attempt to recreate the experiment, leading Frank to test the process on her. Zoe is revived -- but something evil is within her.', NULL, NULL, 2.2444, 5.302, 0, 1.14000000000000012e+00, '2026-07-30 18:28:39', '2026-07-30 18:28:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (5943, 158011, 'tt1911644', NULL, 'The Call', 'The Call', 'movie', 2013, 'https://image.tmdb.org/t/p/w500/mG334OlDVJpD8gMfTCM2Mpp0gQH.jpg', 'https://image.tmdb.org/t/p/original/9jih8et3fkd0Zdo4NHf3cnPj05Z.jpg', 'Jordan Turner is an experienced 911 operator but when she makes an error in judgment and a call ends badly, Jordan is rattled and unsure if she can continue. But when teenager Casey Welson is abducted in the back of a man''s car and calls 911, Jordan is the one called upon to use all of her experience, insights and quick thinking to help Casey escape, and not just to save her, but to make sure the man is brought to justice.', NULL, NULL, 5.1648, 6.79, 0, 1.01, '2026-07-30 18:28:39', '2026-07-30 18:28:39');
