INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6039, 354287, 'tt4758646', NULL, 'War Machine', 'War Machine', 'movie', 2017, 'https://image.tmdb.org/t/p/w500/bU2Q2rCH5VFrJNKSyx6wSmQZFsX.jpg', 'https://image.tmdb.org/t/p/original/eQsellX1IeGaIjv1w4JBzoOrvmf.jpg', 'A rock star general bent on winning the “impossible” war in Afghanistan takes us inside the complex machinery of modern war. Inspired by the true story of General Stanley McChrystal.', NULL, NULL, 3.1973, 5.613, 0, 1.03, '2026-07-30 18:28:39', '2026-07-30 18:28:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6040, 44833, 'tt1440129', NULL, 'Battleship', 'Battleship', 'movie', 2012, 'https://image.tmdb.org/t/p/w500/9b0Im7SfedHiajTwzSL9zGyBI7M.jpg', 'https://image.tmdb.org/t/p/original/85PMh0cKywekAJYDnRXfezYAmEc.jpg', 'When mankind beams a radio signal into space, a reply comes from ‘Planet G’, in the form of several alien crafts that splash down in the waters off Hawaii. Lieutenant Alex Hopper is a weapons officer assigned to the USS John Paul Jones, part of an international naval coalition which becomes the world''s last hope for survival as they engage the hostile alien force of unimaginable strength. While taking on the invaders, Hopper must also try to live up to the potential that his brother, and his fiancée''s father—an Admiral—expect of him.', NULL, NULL, 9.3039, 5.9, 0, 1.01, '2026-07-30 18:28:39', '2026-07-30 18:28:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6041, 848326, 'tt14998742', NULL, 'Rebel Moon - Part One: A Child of Fire', 'Rebel Moon - Part One: A Child of Fire', 'movie', 2023, 'https://image.tmdb.org/t/p/w500/ui4DrH1cKk2vkHshcUcGt2lKxCm.jpg', 'https://image.tmdb.org/t/p/original/w4d1jESRZK12oTMMgmh0IWqlHw.jpg', 'When the ruthless forces of the Motherworld threaten a quiet farming village on a distant moon, a mysterious outsider becomes its best hope for survival.', NULL, NULL, 8.3103, 6.22, 0, 1.01, '2026-07-30 18:28:39', '2026-07-30 18:28:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6042, NULL, NULL, 680, 'Enemy Territory: Quake Wars', 'Enemy Territory: Quake Wars', 'game', 2007, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2o4l.jpg', NULL, 'Enemy Territory: Quake Wars is a first-person shooter video game developed by Splash Damage and published by Activision for Microsoft Windows, Linux, Mac OS X, PlayStation 3 and Xbox 360. The prequel to Quake II, Quake Wars is set in the same science fiction universe as Quake II and Quake 4, with a minimal back-story serving as a prequel to Quake II. It is the second multiplayer-focused game in the Quake series after Quake III Arena.

Quake Wars features similar gameplay to Wolfenstein: Enemy Territory, but with the addition of controllable vehicles and aircraft as well as multiple AI deployables, asymmetric teams, much larger maps and the option of computer-controlled bot opponents. Unlike the previous Enemy Territory games, Quake Wars is a commercial release rather than a free download.

Enemy Territory: Quake Wars received mostly positive reviews upon release, although it received some criticism on consoles.', 'https://www.igdb.com/games/enemy-territory-quake-wars', '["PlayStation 3", "Linux", "PC (Microsoft Windows)", "Mac", "Xbox 360"]', NULL, NULL, 0, 1.03, '2026-07-30 18:28:39', '2026-07-30 18:28:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6043, 11470, 'tt0211443', NULL, 'Jason X', 'Jason X', 'movie', 2001, 'https://image.tmdb.org/t/p/w500/ggOND0hfoE0f3K857joSzEeIchb.jpg', 'https://image.tmdb.org/t/p/original/fR5Hkf4OH6aLExl2qP2ucMV2Xdt.jpg', 'In the year 2455, Old Earth is now a contaminated planet abandoned for centuries -- a brown world of violent storms, toxic landmasses and poisonous seas. Yet humans have returned to the deadly place that they once fled, not to live, but to research the ancient, rusting artifacts of the long-gone civilizations. But it''s not the harmful environment that could prove fatal to the intrepid, young explorers who have just landed on Old Earth. For them, it''s Friday the 13th, and Jason lives!', NULL, NULL, 5.5587, 4.854, 0, 1.01, '2026-07-30 18:28:39', '2026-07-30 18:28:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6044, NULL, NULL, 230, 'StarCraft', 'StarCraft', 'game', 1998, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9n6m.jpg', NULL, 'StarCraft is a real-time strategy game set in a distant sector of the Milky Way galaxy in the 26th century. Players command one of three species across separate campaigns: the Terrans, resourceful human colonists cut off from Earth; the Zerg, an insectoid swarm that assimilates other species; and the Protoss, a technologically advanced race with powerful psionic abilities. Each species features distinct units, structures, and strategic options. The game includes a story-driven single-player campaign for each faction and competitive multiplayer via Battle.net.', 'https://www.igdb.com/games/starcraft', '["PC (Microsoft Windows)", "Mac"]', NULL, NULL, 0, 1.01, '2026-07-30 18:28:39', '2026-07-30 18:28:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6045, 59178, 'tt0192802', NULL, 'The Wind in the Willows', 'The Wind in the Willows', 'movie', 1995, 'https://image.tmdb.org/t/p/w500/oDXSed3TihGrQsNUbns5oIE8Urj.jpg', 'https://image.tmdb.org/t/p/original/ebLDUPt6hQPgAqvINEASBFe7B9k.jpg', 'Jailed for his reckless driving, rambunctious Mr. Toad has to escape from prison when his beloved Toad Hall comes under threat from the wily weasels, who plan to build a dog food factory on the very meadow sold to them by Toad himself.', NULL, NULL, 1.3502, 7.138, 0, 1.01, '2026-07-30 18:28:39', '2026-07-30 18:28:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6046, 1782, 'tt0940580', NULL, 'Afterwards', 'Afterwards', 'movie', 2008, 'https://image.tmdb.org/t/p/w500/byElFR4rU7aU8FQoorVNmIxCSUV.jpg', 'https://image.tmdb.org/t/p/original/k2UCLlYQIy0nj2M8jtSwAHW442u.jpg', 'Newly divorced lawyer Nathan Del Amico is shaken up after he meets a doctor who claims that he can sense when select people are about to die. Though he doesn''t believe the doctor, events in Nathan''s life slowly make him think he''s not long for this world.', NULL, NULL, 1.4448, 5.5, 0, 1.01, '2026-07-30 18:28:39', '2026-07-30 18:28:39');
