INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6048, 1701, 'tt0118880', NULL, 'Con Air', 'Con Air', 'movie', 1997, 'https://image.tmdb.org/t/p/w500/kOKjgrEzGOP92rVQ6srA9jtp60l.jpg', 'https://image.tmdb.org/t/p/original/vsmlShNNHrYlERZaqMOsZ3YctoO.jpg', 'Newly-paroled former US Army ranger Cameron Poe is headed back to his wife, but must fly home aboard a prison transport flight dubbed "Jailbird" taking the “worst of the worst” prisoners, a group described as “pure predators”, to a new super-prison. Poe faces impossible odds when the transport plane is skyjacked mid-flight by the most vicious criminals in the country led by the mastermind — genius serial killer Cyrus "The Virus" Grissom, and backed by black militant Diamond Dog and psychopath Billy Bedlam.', NULL, NULL, 13.2432, 6.784, 0, 1.01, '2026-07-30 18:28:39', '2026-07-30 18:28:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6049, 10477, 'tt0132245', NULL, 'Driven', 'Driven', 'movie', 2001, 'https://image.tmdb.org/t/p/w500/8tJ4Ya8yEyxCMihDumEyvwvUuLB.jpg', 'https://image.tmdb.org/t/p/original/rODTjAT8q1u4ZXIVTCwsBbZo3EE.jpg', 'Talented rookie race-car driver Jimmy Bly has started losing his focus and begins to slip in the race rankings. It''s no wonder, with the immense pressure being shoveled on him by his overly ambitious promoter brother as well as Bly''s romance with his arch rival''s girlfriend Sophia. With much riding on Bly, car owner Carl Henry brings former racing star Joe Tanto on board to help Bly. To drive Bly back to the top of the rankings, Tanto must first deal with the emotional scars left over from a tragic racing accident which nearly took his life.', NULL, NULL, 3.0931, 5.145, 0, 1.01, '2026-07-30 18:28:39', '2026-07-30 18:28:39');
