INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6057, 51540, 'tt1499658', NULL, 'Horrible Bosses', 'Horrible Bosses', 'movie', 2011, 'https://image.tmdb.org/t/p/w500/uQkUwgyFHAm0jGQERPG6Z9o9Zbj.jpg', 'https://image.tmdb.org/t/p/original/9fkYHcOtaz4cKmlDWw7tqUr5TUt.jpg', 'For Nick, Kurt and Dale, the only thing that would make the daily grind more tolerable would be to grind their intolerable bosses into dust. Quitting is not an option, so, with the benefit of a few-too-many drinks and some dubious advice from a hustling ex-con, the three friends devise a convoluted and seemingly foolproof plan to rid themselves of their respective employers... permanently.', NULL, NULL, 6.158, 6.574, 0, 1.01, '2026-07-30 18:28:39', '2026-07-30 18:28:39');
