INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6059, 9522, 'tt0396269', NULL, 'Wedding Crashers', 'Wedding Crashers', 'movie', 2005, 'https://image.tmdb.org/t/p/w500/lFM3lk2zVzC1YFnKm0r6LbFPyRu.jpg', 'https://image.tmdb.org/t/p/original/uTBNMyN3RjMGR1cmtE9RPTDlkZY.jpg', 'John and his buddy Jeremy are emotional criminals who know how to use a woman''s hopes and dreams for their own carnal gain. Their modus operandi: crashing weddings. Normally, they meet guests who want to toast the romantic day with a random hook-up. But when John meets Claire, he discovers what true love – and heartache – feels like.', NULL, NULL, 6.7125, 6.501, 0, 1.01, '2026-07-30 18:28:39', '2026-07-30 18:28:39');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6060, 82702, 'tt1646971', NULL, 'How to Train Your Dragon 2', 'How to Train Your Dragon 2', 'movie', 2014, 'https://image.tmdb.org/t/p/w500/d13Uj86LdbDLrfDoHR5aDOFYyJC.jpg', 'https://image.tmdb.org/t/p/original/8AAuJtCzaibYkbE0QVHc8EBsELB.jpg', 'Five years after uniting the dragons and Vikings of Berk, Hiccup and Toothless soar beyond their homeland, charting the vast unknown. During one of their adventures, the pair discover a secret cave that houses hundreds of wild dragons -- and a mysterious dragon rider with a startling connection to Hiccup. And as the ruthless dragon conqueror Drago Bludvist rises to seize control of both dragons and people alike, Hiccup must step into his role as a true leader and, alongside his friends and Toothless, protect Berk from a devastating war.', NULL, NULL, 14.2619, 7.685, 0, 1.01, '2026-07-30 18:28:39', '2026-07-30 18:28:39');
