UPDATE "recommendations" SET "tmdb_id"=950396, "imdb_id"='tt13654226', "igdb_id"=NULL, "title"='The Gorge', "original_title"='The Gorge', "media_type"='movie', "release_year"=2025, "poster_url"='https://image.tmdb.org/t/p/w500/7iMBZzVZtG0oBug4TfqDb9ZxAOa.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/9nhjGaFLKtddDPtPaX5EmKqsWdH.jpg', "overview"='Two highly trained operatives grow close from a distance after being sent to guard opposite sides of a mysterious gorge. When an evil below emerges, they must work together to survive what lies within.', "external_url"=NULL, "platforms"=NULL, "popularity"=29.7582, "vote_average"=7.678, "is_ambiguous"=0, "evidence_score"=5.3275, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-07-30 18:28:39' WHERE "id"=1921;
UPDATE "recommendations" SET "tmdb_id"=8814, "imdb_id"='tt0419706', "igdb_id"=NULL, "title"='Doom', "original_title"='Doom', "media_type"='movie', "release_year"=2005, "poster_url"='https://image.tmdb.org/t/p/w500/y50lH061yWOvEstoZRn7lYs0huk.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/9EpgaLS44zlXoTSAOhGiJmkIA4B.jpg', "overview"='A team of space marines known as the Rapid Response Tactical Squad, led by Sarge, is sent to a science facility on Mars after somebody reports a security breach. There, they learn that the alert came after a test subject, a mass murderer purposefully injected with alien DNA, broke free and began killing people. Dr. Grimm, who is related to team member Reaper, informs them all that the chromosome can mutate humans into monsters -- and is highly infectious.', "external_url"=NULL, "platforms"=NULL, "popularity"=6.0817, "vote_average"=5.2, "is_ambiguous"=0, "evidence_score"=16.604, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-07-30 18:28:39' WHERE "id"=1926;
UPDATE "recommendations" SET "tmdb_id"=2742, "imdb_id"='tt0102511', "igdb_id"=NULL, "title"='Naked Lunch', "original_title"='Naked Lunch', "media_type"='movie', "release_year"=1991, "poster_url"='https://image.tmdb.org/t/p/w500/u01kh5jKUWjhom76mguRqUgdvja.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/mBteXONDhdVyXRNxj54eMNGNqyT.jpg', "overview"='Blank-faced bug killer Bill Lee and his dead-eyed wife, Joan, like to get high on Bill''s pest poisons while lounging with Beat poet pals. After meeting the devilish Dr. Benway, Bill gets a drug made from a centipede. Upon indulging, he accidentally kills Joan, takes orders from his typewriter-turned-cockroach, ends up in a constantly mutating Mediterranean city and learns that his hip friends have published his work -- which he doesn''t remember writing.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.9292, "vote_average"=6.995, "is_ambiguous"=0, "evidence_score"=16.5375, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-07-30 18:28:39' WHERE "id"=1931;
