UPDATE "recommendations" SET "tmdb_id"=NULL, "imdb_id"=NULL, "igdb_id"=1062, "title"='Alan Wake', "original_title"='Alan Wake', "media_type"='game', "release_year"=2010, "poster_url"='https://images.igdb.com/igdb/image/upload/t_cover_big/co2dft.jpg', "backdrop_url"=NULL, "overview"='Alan Wake is a psychological horror action-adventure game developed by Remedy Entertainment. The narrative centres on Alan Wake, a bestselling thriller novelist experiencing writer''s block. He travels to the small town of Bright Falls with his wife, Alice, seeking a change of environment. Shortly after their arrival, Alice vanishes under mysterious circumstances.

As Alan searches for her, he discovers pages of a thriller novel he does not recall writing. The events described in these pages begin to manifest in reality, and Alan encounters hostile supernatural entities known as the "Taken," who are controlled by darkness. The gameplay involves navigating Bright Falls and using light to combat these dark forces. The storyline explores themes of reality and fiction, along with the influence of the written word.', "external_url"='https://www.igdb.com/games/alan-wake', "platforms"='["PC (Microsoft Windows)", "Xbox 360"]', "popularity"=NULL, "vote_average"=NULL, "is_ambiguous"=0, "evidence_score"=10.814, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-07-30 18:28:39' WHERE "id"=2182;
