UPDATE "recommendations" SET "tmdb_id"=38368, "imdb_id"='tt1588895', "igdb_id"=NULL, "title"='Uncle Boonmee Who Can Recall His Past Lives', "original_title"='ลุงบุญมีระลึกชาติ', "media_type"='movie', "release_year"=2010, "poster_url"='https://image.tmdb.org/t/p/w500/kPFkC9EBvllCIuDTR7A0DSEK6gJ.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/sraqqxwStjlhe82vb0mGx3VuHsD.jpg', "overview"='Suffering from acute kidney failure, Boonmee has chosen to spend his final days surrounded by his loved ones in the countryside. Surprisingly, the ghost of his deceased wife appears to care for him, and his long lost son returns home in a non-human form. Contemplating the reasons for his illness, Boonmee treks through the jungle with his family to a mysterious hilltop cave—the birthplace of his first life.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.6998, "vote_average"=6.6, "is_ambiguous"=0, "evidence_score"=9.004999999999999e+00, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-07-30 18:28:39' WHERE "id"=3061;
