UPDATE "recommendations" SET "tmdb_id"=200727, "imdb_id"='tt1638002', "igdb_id"=NULL, "title"='Love, Rosie', "original_title"='Love, Rosie', "media_type"='movie', "release_year"=2014, "poster_url"='https://image.tmdb.org/t/p/w500/2HOd431LX9ggqSpBIJ7qyYhATyo.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/rpsHpJj7FgnNBXhaO2KFthPwqH6.jpg', "overview"='Since the moment they met at age 5, Rosie and Alex have been best friends, facing the highs and lows of growing up side by side. A fleeting shared moment, one missed opportunity, and the decisions that follow send their lives in completely different directions. As each navigates the complexities of life, love, and everything in between, they always find their way back to each other - but is it just friendship, or something more?', "external_url"=NULL, "platforms"=NULL, "popularity"=5.463, "vote_average"=7.813, "is_ambiguous"=0, "evidence_score"=2.01, "created_at"='2026-07-29 20:51:09', "updated_at"='2026-07-30 18:28:39' WHERE "id"=5542;
UPDATE "recommendations" SET "tmdb_id"=4547, "imdb_id"='tt0258000', "igdb_id"=NULL, "title"='Panic Room', "original_title"='Panic Room', "media_type"='movie', "release_year"=2002, "poster_url"='https://image.tmdb.org/t/p/w500/hANYbvfwxmkC9E4yY6YyJxYxlSJ.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/gJfd2SzUsvY1q1iszthJ3ryuvEA.jpg', "overview"='Trapped in their New York brownstone''s panic room, a hidden chamber built as a sanctuary in the event of break-ins, newly divorced Meg Altman and her young daughter Sarah play a deadly game of cat-and-mouse with three intruders - Burnham, Raoul and Junior - during a brutal home invasion. But the room itself is the focal point because what the intruders really want is inside it.', "external_url"=NULL, "platforms"=NULL, "popularity"=6.8033, "vote_average"=6.793, "is_ambiguous"=0, "evidence_score"=3.0166666666666666e+00, "created_at"='2026-07-29 20:51:09', "updated_at"='2026-07-30 18:28:39' WHERE "id"=5543;
